-- The two checklists published on 2026-10-04: supporting a friend who is
-- struggling (Connection) and breaking a doom-scroll (Habits).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-04`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('when-a-friend-is-struggling', 'When a Friend Is Struggling', 'For when someone you care about is having a hard time and you are not sure what to say. It helps you offer something concrete, ask the question people avoid asking, and keep enough of yourself back that you can stay in it.', 'Connection', '["Send one short message with no question in it — it tells them you are there without asking for a reply.", "Offer one specific thing instead of anything you need — a named offer is far easier to accept.", "Ask how they are doing, then wait through the pause — the real answer usually comes second.", "Ask directly whether they are thinking of suicide — the question does not plant the idea, and it opens the door.", "Save 988 in your phone and theirs — call or text reaches a crisis counselor any hour of the day.", "Say plainly that you do not have the answer — honesty is better company than advice.", "Set a reminder to check back in three days — being remembered later matters more than the first call.", "Tell one other person what you are carrying — holding someone up works better when you are not alone."]'::jsonb, 'as needed', array['Relationships', 'Communication']::text[], 1, '2026-10-04T16:00:00+00:00'::timestamptz),
  ('putting-the-phone-down-mid-scroll', 'Putting the Phone Down Mid-Scroll', 'For the half hour that disappears into bad news and other people''s lives. It helps you notice you are scrolling, break the loop without deleting everything, and put the phone somewhere you have to stand up to reach.', 'Habits', '["Say out loud what you opened the app to do — most scrolls start with no errand at all.", "Put the phone face down an arm''s length away — a small distance breaks the reach-and-tap habit.", "Turn off badges for the two worst apps — a red dot is a request you never agreed to.", "Set a timer for the scroll instead of banning it — a known end makes stopping possible.", "Swap the app on your home screen for a dull one — the thumb goes where the icon used to be.", "Name the feeling that made you pick it up — boredom, dread and loneliness each want something different.", "Read one long thing instead of twenty short ones — attention recovers when it is given somewhere to land.", "Stand up and do one two-minute task — the loop breaks more easily through your body than your will."]'::jsonb, 'as needed', array['Habits', 'Worry']::text[], 1, '2026-10-04T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
